import sys

def main():
    s = sys.stdin.read().split()[0]
    M = 10 ** 9 + 7
    dp = [1]
    for ch in s:
        if ch == '(':
            dp = [(x + y) % M for x, y in zip([0] + dp, dp + [0])]
        else:
            if len(dp) == 1:
                print(0)
                return
            dp = [(x + y) % M for x, y in zip(dp[1:], dp[:-1])]
    print(dp[0] % M if len(dp) == 1 else 0)

