import sys

s = sys.stdin.read().split()[0]
M = 10 ** 9 + 7
cur = {(0, 0): 1}
for ch in s:
    nxt = {}
    for (a, b), w in cur.items():
        if ch == '(':
            moves = [(a + 1, b), (a, b + 1)]
        else:
            moves = []
            if a > 0:
                moves.append((a - 1, b))
            if b > 0:
                moves.append((a, b - 1))
        for st in moves:
            nxt[st] = (nxt.get(st, 0) + w) % M
    cur = nxt
print(cur.get((0, 0), 0) % M)

